import { cpuModel } from '../../documentation/docs/.vitepress/theme/perf-figures.mjs';

// The capacity-planning page's generated blocks (docs-performance.mjs writes them between their markers): the unit
// costs per command (`unit-costs`, T1) and the worked example (`example`), both from the Actions snapshot's headline,
// so a figure is never computed across two reports. A unit cost is beta.6's own L3 rounds at 100k accounts (the
// median of its rounds r1 to r3, at the rate they ran at) or an L4 sustainable rate's total; the example reads the
// rows it names and says which.

export const SNAPSHOT = 'actions-snapshot';
const AXON = 'actions-axon';

