const STORES = { postgres: 'PostgreSQL', mongo: 'MongoDB' };
const number = (value, digits = 1) =>
  value.toLocaleString('en-US', { maximumFractionDigits: digits });
const rate = value => `${number(value)}/s`;
const median = values => {
  const sorted = values.filter(Number.isFinite).sort((a, b) => a - b);
  if (sorted.length === 0) return undefined;
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

const headlineOf = (headlines, report) => {
  const headline = headlines.find(h => h.report === report);
  if (!headline)
    throw new Error(`the capacity blocks need the ${report} headline`);
  return headline;
};

/**
 * The unit-cost rows (T1), each `{ key, store, rate, at, node, database, bus, total, commits, wal, cpu, jdk, commit }`:
 * per L3 suite at 100k accounts, the median of beta.6's rounds r1 to r3 (each at the rate the suite's calibration
 * chose); then per L4 sustainable rate, its total CPU only (the capacity suite does not split it).
 */
export function unitCostRows(headline) {
  const rounds = new Map();
  for (const f of headline.figures) {
    if (f.kind !== 'unit' || f.accounts !== 100000 || !/\.r\d-head$/.test(f.id))
      continue;
    const suite = f.id.replace(/\.r\d-head$/, '');
    rounds.set(suite, [...(rounds.get(suite) ?? []), f]);
  }
  const fromRounds = [...rounds.values()].map(figures => {
    const [first] = figures;
    const of = field => median(figures.map(f => f[field]));
    return {
      key: `${first.scenario}|${first.keys}`,
      store: first.store,
      rate: of('rate'),
      at: 'rounds',
      node: of('nodeCpuMsPerOp'),
      database: of('storeCpuMsPerOp'),
      bus: of('busCpuMsPerOp'),
      total: of('value'),
      commits: of('commitsPerOp'),
      wal: of('walBytesPerOp'),
      cpu: first.cpu,
      jdk: first.jdk,
      commit: first.commit,
    };
  });
  const sustainable = headline.figures
    .filter(f => f.kind === 'sustainable')
    .map(f => ({
      key: `${f.scenario}|${f.keys}`,
      store: f.store,
      rate: f.value,
      at: 'sustainable',
      total: f.cpuMsPerOp,
      cpu: f.cpu,
      jdk: f.jdk,
      commit: f.commit,
    }));
  const order = Object.keys(WORDS.en.workloads);
  return [...fromRounds, ...sustainable].sort(
    (a, b) =>
      a.store.localeCompare(b.store) * -1 ||
      order.indexOf(a.key) - order.indexOf(b.key) ||
      a.rate - b.rate,
  );
}

const cell = (words, value, digits, split = true) =>
  Number.isFinite(value)
    ? number(value, digits)
    : split
      ? words.notMeasured
      : words.notSplit;

/** T1 in `locale`: a row per workload, store and rate, each naming its runner's CPU, its JDK and its build. */
export function unitCostsBlock(locale, headlines) {
  const words = WORDS[locale];
  const rows = unitCostRows(headlineOf(headlines, SNAPSHOT));
  const distinct = field => [...new Set(rows.map(r => r[field]))].sort();
  return [
    words.generated,
    '',
    words.where(distinct('commit'), distinct('jdk')),
    '',
    words.head,
    '| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | --- |',
    ...rows.map(row => {
      const split = row.at === 'rounds';
      const cells = [
        words.workloads[row.key] ?? row.key,
        STORES[row.store],
        [rate(row.rate), words.at[row.at]]
          .filter(Boolean)
          .join(words.separator),
        cell(words, row.node, 3, split),
        cell(words, row.database, 3, split),
        cell(words, row.bus, 3, split),
        cell(words, row.total, 2),
        split ? cell(words, row.commits, 3) : words.notSplit,
        split ? cell(words, row.wal, 0) : words.notSplit,
        cpuModel(row.cpu),
      ];
      return `| ${cells.join(' | ')} |`;
    }),
  ].join('\n');
}

/** The worked example's inputs: PostgreSQL, writes and saga steps a second, accounts, commits a day, years kept. */
export const EXAMPLE = {
  store: 'postgres',
  load: [
    { key: 'E1|uniform', rate: 2000 },
    { key: 'E3|uniform', rate: 500 },
  ],
  accounts: 2_000_000,
  commitsADay: 1_000_000,
  years: 3,
  share: 0.6,
  footprint: 'footprint.axon-pg.100k.wow',
};

/**
 * The worked example's outputs, each with the rows it read: nodes by the sustainable rates (T2), the node's and the
 * database's CPU, commits and WAL a second from the L3 rounds (T1), and storage from Wow's bytes per event and per
 * snapshot in the Actions comparison with Axon (EXAMPLE.footprint, the larger of its two sessions).
 */
export function exampleOutputs(headlines, example = EXAMPLE) {
  const rows = unitCostRows(headlineOf(headlines, SNAPSHOT)).filter(
    r => r.store === example.store,
  );
  const pick = (key, at) => {
    const row = rows.find(r => r.key === key && r.at === at);
    if (!row)
      throw new Error(
        `the example needs a ${at} row for ${key} on ${example.store}`,
      );
    return row;
  };
  const load = example.load.map(l => ({
    ...l,
    unit: pick(l.key, 'rounds'),
    peak: pick(l.key, 'sustainable'),
  }));
  const sum = field =>
    load.reduce((total, l) => total + l.rate * l.unit[field], 0);
  const nodesByRate = load.reduce(
    (total, l) => total + l.rate / l.peak.rate,
    0,
  );
  const footprint = headlineOf(headlines, AXON).figures.find(
    f => f.id === example.footprint,
  );
  if (!footprint)
    throw new Error(
      `the example needs ${example.footprint} in the ${AXON} headline`,
    );
  // The larger of the suite's two sessions.
  const perEvent = Math.max(...footprint.bytesPerEvent);
  const perSnapshot = Math.max(...footprint.bytesPerSnapshot);
  return {
    load,
    nodesByRate,
    nodes: Math.ceil(nodesByRate / example.share) + 1,
    nodeCores: sum('node') / 1000,
    databaseCores: sum('database') / 1000,
    commits: sum('commits'),
    walBytes: sum('wal'),
    perEvent,
    perSnapshot,
    footprint,
    storageBytes: example.commitsADay * perEvent * 365 * example.years,
    snapshotBytes: example.accounts * perSnapshot,
  };
}

/** The worked example in `locale`: its inputs, then each output with the rows it read. */
export function exampleBlock(locale, headlines) {
  const words = WORDS[locale];
  const e = words.example;
  const out = exampleOutputs(headlines);
  const where = row =>
    [cpuModel(row.cpu), `\`${row.commit}\``].join(words.separator);
  const t1 = out.load
    .map(l =>
      [e.t1(words.workloads[l.key], rate(l.unit.rate)), where(l.unit)].join(
        words.separator,
      ),
    )
    .join(words.list);
  const t2 = out.load
    .map(l =>
      [e.t2(words.workloads[l.key], rate(l.peak.rate)), where(l.peak)].join(
        words.separator,
      ),
    )
    .join(words.list);
  const axon = [
    e.axon,
    cpuModel(out.footprint.cpu),
    `\`${out.footprint.commit}\``,
  ].join(words.separator);
  const gb = bytes => e.gb(number(bytes / 1e9, 1));
  const rows = [
    [
      e.rows.nodesByRate,
      e.nodes(`${number(out.nodesByRate * 100, 0)}%`, out.nodes - 1, out.nodes),
      t2,
    ],
    [
      e.rows.nodeCores,
      e.cores(
        number(out.nodeCores, 2),
        number(out.nodeCores / EXAMPLE.share, 2),
      ),
      t1,
    ],
    [e.rows.databaseCores, e.cores1(number(out.databaseCores, 2)), t1],
    [e.rows.commits, e.perSecond(number(out.commits, 0)), t1],
    [e.rows.wal, e.mbPerSecond(number(out.walBytes / 1e6, 2)), t1],
    [
      e.rows.storage,
      gb(out.storageBytes / EXAMPLE.years),
      [e.footprint(out.perEvent, e.event), axon].join(words.separator),
    ],
    [
      e.rows.snapshots,
      gb(out.snapshotBytes),
      [e.footprint(out.perSnapshot, e.snapshot), axon].join(words.separator),
    ],
  ];
  return [
    words.generated,
    '',
    e.inputs,
    '',
    e.head,
    '| --- | --- | --- |',
    ...rows.map(r => `| ${r.join(' | ')} |`),
  ].join('\n');
}
